package com.samaksh.farms.retro;
import org.springframework.stereotype.Component;
import java.util.*;
import java.util.zip.*;
import java.io.*;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.*;
@Component
public class RetroSpreadsheet {
 public List<Map<String,String>> read(String filename,byte[] bytes) {
  if(bytes.length>5_000_000)throw new IllegalArgumentException("File must be under 5 MB");
  try {return filename.toLowerCase().endsWith(".csv")?csv(new String(bytes,java.nio.charset.StandardCharsets.UTF_8)):xlsx(bytes);}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("Unable to read workbook. Use the template in .xlsx or UTF-8 CSV format.");}
 }
 private Document xml(byte[] data)throws Exception {var f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);f.setXIncludeAware(false);f.setExpandEntityReferences(false);return f.newDocumentBuilder().parse(new ByteArrayInputStream(data));}
 private List<Map<String,String>> xlsx(byte[] bytes)throws Exception{
  Map<String,byte[]> files=new HashMap<>();int size=0,count=0;
  try(var zip=new ZipInputStream(new ByteArrayInputStream(bytes))){ZipEntry entry;while((entry=zip.getNextEntry())!=null){if(++count>200)throw new IllegalArgumentException("Workbook contains too many parts");var out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int read;while((read=zip.read(buffer))!=-1){size+=read;if(size>20_000_000)throw new IllegalArgumentException("Workbook is too large when expanded");out.write(buffer,0,read);}files.put(entry.getName(),out.toByteArray());}}
  if(!files.containsKey("xl/workbook.xml")||!files.containsKey("xl/_rels/workbook.xml.rels"))throw new IllegalArgumentException("Use an .xlsx workbook with the Data sheet first; .xls files must be saved as .xlsx");
  var workbook=xml(files.get("xl/workbook.xml"));var props=workbook.getElementsByTagName("workbookPr");if(props.getLength()>0&&Set.of("1","true").contains(((Element)props.item(0)).getAttribute("date1904")))throw new IllegalArgumentException("For workbooks using the 1904 date system, convert dates to YYYY-MM-DD text before importing");
  var sheetNodes=workbook.getElementsByTagName("sheet");if(sheetNodes.getLength()==0)throw new IllegalArgumentException("No data sheet found");String relationship=((Element)sheetNodes.item(0)).getAttribute("r:id");String sheetPath=null;var relations=xml(files.get("xl/_rels/workbook.xml.rels")).getElementsByTagName("Relationship");for(int i=0;i<relations.getLength();i++){var relation=(Element)relations.item(i);if(relationship.equals(relation.getAttribute("Id"))){if("External".equals(relation.getAttribute("TargetMode")))throw new IllegalArgumentException("External worksheets are not supported");String target=relation.getAttribute("Target");sheetPath=target.startsWith("/")?target.substring(1):"xl/"+target;}}
  if(sheetPath==null||sheetPath.contains("..")||!files.containsKey(sheetPath))throw new IllegalArgumentException("First worksheet cannot be read");
  List<String> shared=new ArrayList<>();if(files.containsKey("xl/sharedStrings.xml")){var nodes=xml(files.get("xl/sharedStrings.xml")).getElementsByTagName("si");for(int i=0;i<nodes.getLength();i++)shared.add(nodes.item(i).getTextContent());}
  List<List<String>> rows=new ArrayList<>();var nodes=xml(files.get(sheetPath)).getElementsByTagName("row");
  for(int i=0;i<nodes.getLength();i++){var row=(Element)nodes.item(i);var cells=row.getElementsByTagName("c");List<String> values=new ArrayList<>();for(int j=0;j<cells.getLength();j++){var cell=(Element)cells.item(j);if(cell.getElementsByTagName("f").getLength()>0)throw new IllegalArgumentException("Row "+row.getAttribute("r")+" contains a formula. Paste values before importing.");String ref=cell.getAttribute("r").replaceAll("[0-9]","");int col=0;for(char c:ref.toCharArray())col=col*26+c-'A'+1;if(col<=0||col>80)throw new IllegalArgumentException("Too many columns");while(values.size()<col)values.add("");var v=cell.getElementsByTagName("v");String text=v.getLength()==0?"":v.item(0).getTextContent();if("inlineStr".equals(cell.getAttribute("t")))text=cell.getTextContent();if("s".equals(cell.getAttribute("t")))text=shared.get(Integer.parseInt(text));values.set(col-1,text.trim());}rows.add(values);if(rows.size()>201)throw new IllegalArgumentException("Import at most 200 rows at a time");}
  return maps(rows);
 }
 private List<Map<String,String>> csv(String text){List<List<String>> rows=new ArrayList<>();List<String> row=new ArrayList<>();StringBuilder value=new StringBuilder();boolean quoted=false;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(c=='"'){if(quoted&&i+1<text.length()&&text.charAt(i+1)=='"'){value.append('"');i++;}else quoted=!quoted;}else if(c==','&&!quoted){row.add(value.toString());value.setLength(0);}else if((c=='\n'||c=='\r')&&!quoted){if(c=='\r'&&i+1<text.length()&&text.charAt(i+1)=='\n')i++;row.add(value.toString());rows.add(row);row=new ArrayList<>();value.setLength(0);}else value.append(c);}if(quoted)throw new IllegalArgumentException("Unclosed CSV quote");if(!row.isEmpty()||!value.isEmpty()){row.add(value.toString());rows.add(row);}return maps(rows);}
 private List<Map<String,String>> maps(List<List<String>> rows){if(rows.isEmpty())throw new IllegalArgumentException("No rows found");var headers=rows.getFirst().stream().map(s->s.replace("\uFEFF","").trim()).toList();if(new HashSet<>(headers).size()!=headers.size()||headers.stream().anyMatch(String::isBlank))throw new IllegalArgumentException("Column headings must be unique and nonempty");List<Map<String,String>> result=new ArrayList<>();for(int i=1;i<rows.size();i++){var row=rows.get(i);if(row.stream().allMatch(String::isBlank))continue;if(row.size()>headers.size()&&row.subList(headers.size(),row.size()).stream().anyMatch(s->!s.isBlank()))throw new IllegalArgumentException("Row "+(i+1)+" has extra columns");var value=new LinkedHashMap<String,String>();for(int c=0;c<headers.size();c++)value.put(headers.get(c),c<row.size()?row.get(c).trim():"");result.add(value);}if(result.size()>200)throw new IllegalArgumentException("Import at most 200 rows");return result;}
}
